-- The Wifii / Culture Lives Here: Cloudflare D1 schema
-- Generated by `npm run db:generate`. Edit src/lib/collections.ts or src/lib/seed-data.ts, not this file.
-- Apply with: npx wrangler d1 execute thewifii-db --remote --file=./schema.sql

-- Articles & Reviews: Culture Lives Here articles, 5 Flame reviews and Creator Corner posts.
CREATE TABLE IF NOT EXISTS posts (
  id TEXT PRIMARY KEY,
  title TEXT NOT NULL,
  slug TEXT,
  type TEXT NOT NULL,
  format TEXT,
  category TEXT,
  review_kind TEXT,
  flame_score REAL, -- 0.0 to 5.0
  excerpt TEXT,
  body TEXT,
  cover_image TEXT,
  author TEXT,
  tags TEXT, -- JSON array
  embeds TEXT, -- JSON array
  read_time REAL,
  featured INTEGER, -- 0 or 1
  status TEXT NOT NULL,
  published_at TEXT,
  created_at TEXT NOT NULL,
  updated_at TEXT NOT NULL
);
CREATE INDEX IF NOT EXISTS idx_posts_status ON posts (status);
CREATE INDEX IF NOT EXISTS idx_posts_slug ON posts (slug);

-- Podcast Episodes: Episodes for Culture Lives Here Podcast and Culturally Inappropriate Podcast.
CREATE TABLE IF NOT EXISTS episodes (
  id TEXT PRIMARY KEY,
  show TEXT NOT NULL,
  number REAL NOT NULL,
  title TEXT NOT NULL,
  description TEXT,
  show_notes TEXT,
  audio_url TEXT,
  duration REAL,
  cover_image TEXT,
  guests TEXT, -- JSON array
  tags TEXT, -- JSON array
  spotify_url TEXT,
  apple_url TEXT,
  youtube_url TEXT,
  status TEXT NOT NULL,
  published_at TEXT,
  created_at TEXT NOT NULL,
  updated_at TEXT NOT NULL
);
CREATE INDEX IF NOT EXISTS idx_episodes_status ON episodes (status);

-- Portfolio: TikTok Shop & UGC work, brand campaigns and viral videos.
CREATE TABLE IF NOT EXISTS portfolio_items (
  id TEXT PRIMARY KEY,
  title TEXT NOT NULL,
  client TEXT,
  category TEXT NOT NULL,
  media_type TEXT NOT NULL,
  media_url TEXT,
  thumbnail TEXT,
  stats TEXT,
  description TEXT,
  sort REAL,
  status TEXT NOT NULL,
  created_at TEXT NOT NULL,
  updated_at TEXT NOT NULL
);
CREATE INDEX IF NOT EXISTS idx_portfolio_items_status ON portfolio_items (status);

-- Music & Sounds: Beats for sale, reference tracks and TikTok Commercial Music Library sounds.
CREATE TABLE IF NOT EXISTS tracks (
  id TEXT PRIMARY KEY,
  kind TEXT NOT NULL,
  title TEXT NOT NULL,
  artist TEXT,
  bpm REAL,
  musical_key TEXT,
  genre TEXT,
  moods TEXT, -- JSON array
  audio_url TEXT,
  cover_image TEXT,
  duration REAL,
  price_mp3 REAL,
  price_wav REAL,
  price_stems REAL,
  tiktok_url TEXT,
  usage_tip TEXT,
  description TEXT,
  sort REAL,
  status TEXT NOT NULL,
  created_at TEXT NOT NULL,
  updated_at TEXT NOT NULL
);
CREATE INDEX IF NOT EXISTS idx_tracks_status ON tracks (status);

-- Playlists: Public editorial playlists with Spotify embeds.
CREATE TABLE IF NOT EXISTS playlists (
  id TEXT PRIMARY KEY,
  title TEXT NOT NULL,
  description TEXT,
  spotify_id TEXT NOT NULL,
  moods TEXT, -- JSON array
  highlights TEXT, -- JSON array
  cover_image TEXT,
  curator TEXT,
  sort REAL,
  status TEXT NOT NULL,
  created_at TEXT NOT NULL,
  updated_at TEXT NOT NULL
);
CREATE INDEX IF NOT EXISTS idx_playlists_status ON playlists (status);

-- Merch: Streetwear and creator merch for the storefront.
CREATE TABLE IF NOT EXISTS products (
  id TEXT PRIMARY KEY,
  name TEXT NOT NULL,
  slug TEXT,
  price REAL NOT NULL,
  category TEXT,
  badge TEXT,
  description TEXT,
  image TEXT,
  gallery TEXT, -- JSON array
  sizes TEXT, -- JSON array
  in_stock INTEGER, -- 0 or 1
  sort REAL,
  status TEXT NOT NULL,
  created_at TEXT NOT NULL,
  updated_at TEXT NOT NULL
);
CREATE INDEX IF NOT EXISTS idx_products_status ON products (status);
CREATE INDEX IF NOT EXISTS idx_products_slug ON products (slug);

-- Dashboard accounts. The admin signs in with the ADMIN_PASSWORD secret and is not stored here.
CREATE TABLE IF NOT EXISTS users (
  id TEXT PRIMARY KEY,
  name TEXT NOT NULL,
  email TEXT NOT NULL UNIQUE,
  role TEXT NOT NULL DEFAULT 'contributor', -- 'admin' or 'contributor'
  password_hash TEXT NOT NULL,              -- PBKDF2-SHA256, never plain text
  created_at TEXT NOT NULL
);

-- Brand inquiries, contact messages, beat inquiries and newsletter signups.
CREATE TABLE IF NOT EXISTS submissions (
  id TEXT PRIMARY KEY,
  kind TEXT NOT NULL,
  name TEXT,
  email TEXT,
  payload TEXT NOT NULL, -- JSON object
  created_at TEXT NOT NULL
);
CREATE INDEX IF NOT EXISTS idx_submissions_created ON submissions (created_at);

-- Key/value settings (for example the Spotify refresh token saved by /api/spotify/callback).
CREATE TABLE IF NOT EXISTS settings (
  key TEXT PRIMARY KEY,
  value TEXT NOT NULL
);
